using MVZ2.Resources;
using MVZ2Logic.Resources;

namespace MVZ2.ResourcePacks
{
    public class ModifiedCharacterLayer : ITalkCharacterLayer
    {
        public ModifiedCharacterLayer(SpriteReference? sprite, float positionX, float positionY)
        {
            Sprite = sprite;
            PositionX = positionX;
            PositionY = positionY;
        }

        public SpriteReference? Sprite { get; set; }
